/* Quick setup example for ${lwip_mqtt_name:raProperty(module.lwip.mqtt_client.name)}.
 */

/* Please change the port number if you want to use another port */
#define ${lwip_mqtt_name_upper:raProperty(module.lwip.mqtt_client.name_upper)}_PORT_NUMBER       8883

/* lwIP MQTT connection information. */
const struct mqtt_connect_client_info_t ${lwip_mqtt_name}_client_info =
{
    "${lwip_mqtt_name}",
    NULL,                              /* user */
    NULL,                              /* pass */
    100,                               /* keep alive */
    NULL,                              /* will_topic */
    NULL,                              /* will_msg */
    0,                                 /* will_qos */
    0                                  /* will_retain */
#if LWIP_ALTCP && LWIP_ALTCP_TLS
    , NULL
#endif
};

mqtt_client_t * g_${lwip_mqtt_name}_client;

void ${lwip_mqtt_name}_quick_setup(void);

/* Quick setup for ${lwip_mqtt_name}. */
void ${lwip_mqtt_name}_quick_setup(void)
{
    ip_addr_t server_ip_address;

    IP4_ADDR(&server_ip_address, 192, 168, 10, 1);

     /* Initialize lwIP MQTT Client */
    g_${lwip_mqtt_name}_client = mqtt_client_new();

    #if ${lwip_mqtt_name_upper}_CONNECTION_CALLBACK_ENABLE
        g_${lwip_mqtt_name}_connected_flag = false;
        assert(ERR_OK == mqtt_client_connect(g_${lwip_mqtt_name}_client, &server_ip_address, ${lwip_mqtt_name_upper}_PORT_NUMBER,
                                             ${lwip_mqtt_conn_callback:raProperty(module.lwip.mqtt_client.conn_callback)}, NULL, &${lwip_mqtt_name}_client_info));

        /* Waiting for connection to be established. */
        while (false == g_${lwip_mqtt_name}_connected_flag)
        {
            #if NO_SYS
                R_BSP_SoftwareDelay(1, BSP_DELAY_UNITS_MILLISECONDS);
                sys_check_timeouts();
            #else
                sys_msleep(1);
            #endif
        }
    #else
        assert(ERR_OK == mqtt_client_connect(g_${lwip_mqtt_name}_client, &server_ip_address, ${lwip_mqtt_name_upper}_PORT_NUMBER,
                                             NULL, NULL, &${lwip_mqtt_name}_client_info));
    #endif
}

/* Quick declare callbacks example for ${lwip_mqtt_name:raProperty(module.lwip.mqtt_client.name)}.
 */

/* TODO: Enable if you want to use a connection callback */
#define ${lwip_mqtt_name_upper:raProperty(module.lwip.mqtt_client.name_upper)}_CONNECTION_CALLBACK_ENABLE (0)
#if ${lwip_mqtt_name_upper}_CONNECTION_CALLBACK_ENABLE
volatile uint8_t g_${lwip_mqtt_name}_connected_flag = false;

void ${lwip_mqtt_conn_callback:raProperty(module.lwip.mqtt_client.conn_callback)}(mqtt_client_t * client, void * arg, mqtt_connection_status_t status);

void ${lwip_mqtt_conn_callback}(mqtt_client_t * client, void * arg, mqtt_connection_status_t status)
{
    FSP_PARAMETER_NOT_USED(client);
    FSP_PARAMETER_NOT_USED(arg);
    if (MQTT_CONNECT_ACCEPTED == status)
    {
        g_${lwip_mqtt_name}_connected_flag = true;
    }
}
#endif

/* TODO: Enable if you want to use a publish - subcribe request callback */
#define ${lwip_mqtt_name_upper}_REQUEST_CALLBACK_ENABLE (0)
#if ${lwip_mqtt_name_upper}_REQUEST_CALLBACK_ENABLE
volatile uint8_t g_${lwip_mqtt_name}_pub_sub_request_flag = false;

void ${lwip_mqtt_request_callback:raProperty(module.lwip.mqtt_client.request_callback)}(void * arg, err_t result);
void ${lwip_mqtt_request_callback}(void * arg, err_t result)
{
    FSP_PARAMETER_NOT_USED(arg);
    if (ERR_OK == result)
    {
        g_${lwip_mqtt_name}_pub_sub_request_flag = true;
    }
}
#endif

/* TODO: Enable if you want to use a incomming message callback */
#define ${lwip_mqtt_name_upper}_INCOMING_MSG_CALLBACK_ENABLE (0)
#if ${lwip_mqtt_name_upper}_INCOMING_MSG_CALLBACK_ENABLE

#define ${lwip_mqtt_name_upper}_INCOMING_MSG_BUF_SIZE  (50)

volatile uint8_t g_${lwip_mqtt_name}_receive_incomming_msg_flag = false;

static char g_${lwip_mqtt_name}_incoming_topic[${lwip_mqtt_name_upper}_INCOMING_MSG_BUF_SIZE];
static unsigned char g_${lwip_mqtt_name}_incoming_msg[${lwip_mqtt_name_upper}_INCOMING_MSG_BUF_SIZE];

void ${lwip_mqtt_incoming_data_callback:raProperty(module.lwip.mqtt_client.incoming_data_callback)}(void * arg, const u8_t * data, u16_t len, u8_t flags);
void ${lwip_mqtt_incoming_publish_callback:raProperty(module.lwip.mqtt_client.incoming_publish_callback)}(void * arg, const char * topic, u32_t tot_len);

void ${lwip_mqtt_incoming_data_callback}(void * arg, const u8_t * data, u16_t len, u8_t flags)
{
    FSP_PARAMETER_NOT_USED(arg);
    if (flags & MQTT_DATA_FLAG_LAST)
    {
        memcpy(g_${lwip_mqtt_name}_incoming_msg, data, len);
        g_${lwip_mqtt_name}_receive_incomming_msg_flag = true;
    }
}

void ${lwip_mqtt_incoming_publish_callback}(void * arg, const char * topic, u32_t tot_len)
{
    FSP_PARAMETER_NOT_USED(arg);
    memcpy(g_${lwip_mqtt_name}_incoming_topic, topic, tot_len);
}

#endif

/* Quick publish example for ${lwip_mqtt_name:raProperty(module.lwip.mqtt_client.name)}.
*  Please call example after calling quick setup example
*/

#define ${lwip_mqtt_name_upper:raProperty(module.lwip.mqtt_client.name_upper)}_PUBLISH_TOPIC      "/lwip/example"

void ${lwip_mqtt_name}_quick_publish_example(void);
/* Quick publish example for ${lwip_mqtt_name}. */
void ${lwip_mqtt_name}_quick_publish_example(void)
{
    const char data[] = "lwIP MQTT Hello world.";

    /* Publish message to MQTT topic with Qos 0 and retain flag disabled */
#if ${lwip_mqtt_name_upper}_REQUEST_CALLBACK_ENABLE
    g_${lwip_mqtt_name}_pub_sub_request_flag = false;
    assert(ERR_OK == mqtt_publish(g_${lwip_mqtt_name}_client, ${lwip_mqtt_name_upper}_PUBLISH_TOPIC, data,
                                  strlen(data), 0, 0,
                                  ${lwip_mqtt_conn_callback:raProperty(module.lwip.mqtt_client.request_callback)}, NULL));

     /* Waiting for publish process completed. */
    while (false == g_${lwip_mqtt_name}_pub_sub_request_flag)
    {
        #if NO_SYS
            R_BSP_SoftwareDelay(1, BSP_DELAY_UNITS_MILLISECONDS);
            sys_check_timeouts();
        #else
            sys_msleep(1);
        #endif
    }
#else
    /* Publish message to MQTT topic with Qos 0 and retain flag disabled */
    assert(ERR_OK == mqtt_publish(g_${lwip_mqtt_name}_client, ${lwip_mqtt_name_upper}_PUBLISH_TOPIC, data,
                                  strlen(data), 0, 0, NULL, NULL));
#endif
}

/* Quick subcribe example for ${lwip_mqtt_name:raProperty(module.lwip.mqtt_client.name)}.*/

#define ${lwip_mqtt_name_upper:raProperty(module.lwip.mqtt_client.name_upper)}_SUBCRIBE_TOPIC      "/lwip/example"

void ${lwip_mqtt_name}_quick_subcribe_example(void);
/* Quick subcribe example for ${lwip_mqtt_name}. */
void ${lwip_mqtt_name}_quick_subcribe_example(void)
{

#if ${lwip_mqtt_name_upper}_INCOMING_MSG_CALLBACK_ENABLE
    g_${lwip_mqtt_name}_receive_incomming_msg_flag = false;

    /* Set callback for receiving incomming messsage from subscribed MQTT topic */
    mqtt_set_inpub_callback(g_${lwip_mqtt_name}_client, ${lwip_mqtt_incoming_publish_callback:raProperty(module.lwip.mqtt_client.incoming_publish_callback)},
                            ${lwip_mqtt_incoming_data_callback:raProperty(module.lwip.mqtt_client.incoming_data_callback)}, NULL);
#endif

#if ${lwip_mqtt_name_upper}_REQUEST_CALLBACK_ENABLE
    g_${lwip_mqtt_name}_pub_sub_request_flag = false;
    /* Subcribe to MQTT topic with Qos 0 */
    assert(ERR_OK == mqtt_subscribe(g_${lwip_mqtt_name}_client, ${lwip_mqtt_name_upper}_SUBCRIBE_TOPIC, 0,
                                    ${lwip_mqtt_conn_callback:raProperty(module.lwip.mqtt_client.request_callback)}, NULL));

     /* Waiting for subcribe process completed. */
    while (false == g_${lwip_mqtt_name}_pub_sub_request_flag)
    {
        #if NO_SYS
            R_BSP_SoftwareDelay(1, BSP_DELAY_UNITS_MILLISECONDS);
            sys_check_timeouts();
        #else
            sys_msleep(1);
        #endif
    }
#else
    /* Subcribe to MQTT topic with Qos 0 */
    assert(ERR_OK == mqtt_subscribe(g_${lwip_mqtt_name}_client, ${lwip_mqtt_name_upper}_SUBCRIBE_TOPIC, 0,
                                    NULL, NULL));
#endif

    /* If ${lwip_mqtt_name_upper}_INCOMING_MSG_CALLBACK_ENABLE macro is enabled, the incoming message from subscribed topic will be stored in g_${lwip_mqtt_name}_incoming_msg
    * and the incoming topic will be stored in g_${lwip_mqtt_name}_incoming_topic, g_${lwip_mqtt_name}_receive_incomming_msg_flag will be set to 1 when receiving incoming
    * message from subscribed topic.
    */

    /* Please add your code */
}

/* Quick unsubscribe example for ${lwip_mqtt_name:raProperty(module.lwip.mqtt_client.name)}.
*  Please use this example after calling quick subscribe example and quick setup example
*/

void ${lwip_mqtt_name}_quick_unsubscribe_example(void);
/* Quick unsubcribe example for ${lwip_mqtt_name}. */
void ${lwip_mqtt_name}_quick_unsubscribe_example(void)
{

#if ${lwip_mqtt_name_upper}_REQUEST_CALLBACK_ENABLE
    g_${lwip_mqtt_name}_pub_sub_request_flag = false;

    /* Unsubcribe to MQTT topic */
    assert(ERR_OK == mqtt_unsubscribe(g_${lwip_mqtt_name}_client, ${lwip_mqtt_name_upper:raProperty(module.lwip.mqtt_client.name_upper)}_SUBCRIBE_TOPIC,
                                      ${lwip_mqtt_conn_callback:raProperty(module.lwip.mqtt_client.request_callback)}, NULL));

     /* Waiting for unsubcribe process completed. */
    while (false == g_${lwip_mqtt_name}_pub_sub_request_flag)
    {
        #if NO_SYS
            R_BSP_SoftwareDelay(1, BSP_DELAY_UNITS_MILLISECONDS);
            sys_check_timeouts();
        #else
            sys_msleep(1);
        #endif
    }
#else
    /* Unsubcribe to MQTT topic */
    assert(ERR_OK == mqtt_unsubscribe(g_${lwip_mqtt_name}_client, ${lwip_mqtt_name_upper:raProperty(module.lwip.mqtt_client.name_upper)}_SUBCRIBE_TOPIC,
                                      NULL, NULL));
#endif

}

/* Quick tear down example for ${lwip_mqtt_name:raProperty(module.lwip.mqtt_client.name)}.
*  Please use this example after calling quick setup example
*/

void ${lwip_mqtt_name}_quick_teardown_example(void);
/* Quick tear down example for ${lwip_mqtt_name}. */
void ${lwip_mqtt_name}_quick_teardown_example(void)
{
    /* Close MQTT connection. */
    mqtt_disconnect(g_${lwip_mqtt_name}_client);
    mqtt_client_free(g_${lwip_mqtt_name}_client);
}
